<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { VacationPlan } from '../domain/types'
import { current, db, editCells, month, notify, removeLeave, removePlan, savePlan, saveLeaveAdjustment, setCalendar } from '../store'
import { addMonths, dateRange, daysInMonth, weekday } from '../domain/dates'
import { activeOn, key, openOn, orderedEmployees } from '../domain/model'
import { vacationOn } from '../domain/absences'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
const tabs = ['开班日历','员工休假计划','事后请假','个人休息'], tab = ref('员工休假计划')
const days = computed(() => daysInMonth(month.value)), offset = computed(() => (new Date(`${month.value}-01T12:00:00`).getDay() + 6) % 7)
const selected = ref(`${month.value}-01`), open = ref(openOn(db.value, selected.value)), reason = ref(''), search = ref('')
watch(month, value => { selected.value = `${value}-01`; open.value = openOn(db.value, selected.value); planOpen.value = false; adjustmentOpen.value = false })
function choose(date: string) { selected.value = date; open.value = openOn(db.value,date); reason.value = '' }
const employees = computed(() => orderedEmployees(db.value).filter(e => days.value.some(d => activeOn(e,d)) && `${e.name}${e.code}`.includes(search.value)))
const plans = computed(() => db.value.vacationPlans.filter(p => p.month === month.value && employees.value.some(e => e.id === p.employeeId)).sort((a,b) => a.dates[0]!.localeCompare(b.dates[0]!)))
const planDays = computed(() => plans.value.reduce((n,p) => n+p.dates.length,0))
const leaves = computed(() => employees.value.flatMap(e => days.value.flatMap(date => {
  const cell = current.value?.cells[key(e.id,date)]
  return cell?.kind === 'leave' ? [{employee:e,date,note:cell.note || ''}] : []
})))
const planOpen = ref(false), planId = ref(''), employeeId = ref(''), from = ref(''), to = ref(''), planReason = ref(''), chosenDates = ref<string[]>([])
function openPlan(plan?: VacationPlan, employee = '', date = '') {
  planId.value = plan?.id || ''; employeeId.value = plan?.employeeId || employee
  from.value = plan?.dates[0] || date || days.value[0]!; to.value = plan?.dates.at(-1) || from.value
  chosenDates.value = plan ? [...plan.dates] : date ? [date] : []; planReason.value = plan?.reason || ''; planOpen.value = true
}
function expandRange(openOnly: boolean) {
  if (!from.value || !to.value || from.value > to.value || !from.value.startsWith(month.value) || !to.value.startsWith(month.value)) { notify('请选择当月有效日期范围','error'); return }
  chosenDates.value = dateRange(from.value,to.value).filter(d => !openOnly || openOn(db.value,d))
}
const affectedShifts = computed(() => chosenDates.value.filter(d => current.value?.cells[key(employeeId.value,d)]?.kind === 'shift').length)
async function submitPlan() {
  if (await savePlan({id:planId.value || undefined,employeeId:employeeId.value,month:month.value,dates:[...chosenDates.value],reason:planReason.value})) planOpen.value = false
}
function cellPlan(employee: string,date: string) {
  const plan = vacationOn(db.value,employee,date)
  openPlan(plan,employee,date)
}
const deletePlan = ref<VacationPlan>(), deleteDate = ref('')
async function confirmRemovePlan() { if (deletePlan.value && await removePlan(deletePlan.value.id,deleteDate.value || undefined)) {deletePlan.value = undefined; planOpen.value = false} }
const previousLeaveDate = ref('')
const adjustmentOpen = ref(false), adjustmentKind = ref<'leave'|'rest'|'unassigned'>('leave'), adjustmentEmployee = ref(''), adjustmentFrom = ref(''), adjustmentTo = ref(''), adjustmentNote = ref('')
function openAdjustment(kind: 'leave'|'rest', employee = '',date = '',note = '') {
  previousLeaveDate.value = kind === 'leave' ? date : ''; adjustmentKind.value = kind; adjustmentEmployee.value = employee; adjustmentFrom.value = date || days.value[0]!; adjustmentTo.value = adjustmentFrom.value; adjustmentNote.value = note; adjustmentOpen.value = true
}
async function saveAdjustment() {
  if (!adjustmentEmployee.value || !adjustmentFrom.value || adjustmentFrom.value > adjustmentTo.value || !adjustmentFrom.value.startsWith(month.value) || !adjustmentTo.value.startsWith(month.value)) {notify('请选择员工及当月日期范围','error'); return}
  const dates = dateRange(adjustmentFrom.value,adjustmentTo.value)
  const success = adjustmentKind.value === 'leave' ? await saveLeaveAdjustment(adjustmentEmployee.value,dates,adjustmentNote.value,previousLeaveDate.value || undefined) : await editCells(adjustmentEmployee.value,dates,{kind:adjustmentKind.value,source:'manual',locked:adjustmentKind.value !== 'unassigned',note:adjustmentNote.value})
  if (success) adjustmentOpen.value = false
}
</script>
<template>
<section class="page-heading"><div><h1>工作日历</h1><p>先确定开班日和员工预定休假，再生成排班；事后请假单独调整。</p></div><div class="month-control"><button class="icon-button" aria-label="工作日历上月" @click="month = addMonths(month,-1)"><Icon name="left" :size="17" /></button><input v-model="month" type="month" aria-label="计划月份" /><button class="icon-button" aria-label="工作日历下月" @click="month = addMonths(month,1)"><Icon name="right" :size="17" /></button></div></section>
<div class="tab-list calendar-tabs"><button v-for="t in tabs" :key="t" :class="{active:tab === t}" @click="tab = t">{{ t }}</button></div>
<div v-if="tab === '开班日历'" class="calendar-layout"><section class="panel"><header class="panel-header"><div><h2>全局开班日历</h2><p>影响每日八班需求及个人默认休息。</p></div><div class="month-control"><button class="icon-button" aria-label="日历上月" @click="month = addMonths(month,-1)"><Icon name="left" :size="17" /></button><input v-model="month" type="month" aria-label="工作日历月份" /><button class="icon-button" aria-label="日历下月" @click="month = addMonths(month,1)"><Icon name="right" :size="17" /></button></div></header><div class="calendar-grid work-calendar"><div v-for="w in ['一','二','三','四','五','六','日']" :key="w" class="calendar-weekday">周{{ w }}</div><div v-for="n in offset" :key="`blank${n}`"></div><button v-for="date in days" :key="date" class="calendar-day" :class="{ off: !openOn(db,date), selected: selected === date, overridden: db.calendar[date] !== undefined }" @click="choose(date)"><strong>{{ Number(date.slice(8)) }}</strong><span>{{ openOn(db,date) ? '开班' : '休息' }}</span><small v-if="db.calendar[date] !== undefined">人工调整</small></button></div><footer class="panel-footer muted">{{ days.filter(d => openOn(db,d)).length }}天开班 · {{ days.filter(d => !openOn(db,d)).length }}天休息</footer></section><aside class="panel day-settings"><h2>{{ selected }}</h2><p class="muted">选择全局日期状态</p><label class="radio-card"><input v-model="open" type="radio" :value="true" /><span><strong>开班日</strong><small>启用班次各需要2人</small></span></label><label class="radio-card"><input v-model="open" type="radio" :value="false" /><span><strong>休息日</strong><small>关闭全部每日需求</small></span></label><label class="field">修改原因<textarea v-model="reason" rows="3" placeholder="例如：节假日调休、周末补班" /></label><button class="button primary full-width" @click="setCalendar(selected,open,reason)">保存日历调整</button><p class="fineprint">会为已确认月份建立修订草稿。人工锁定班次、预定休假与事后请假不被静默删除，冲突在月历中显示。</p></aside></div><template v-if="tab === '员工休假计划'">
<section class="panel"><header class="panel-header"><div><h2>当月员工休假计划 <span class="pill vacation-pill">排班前</span></h2><p>黄色“预”为预定休假。点击表格单元格可新增或调整；不改变全体开班需求。</p></div><button class="button primary" @click="openPlan()"><Icon name="plus" :size="16" />新增休假计划</button></header>
<div class="plan-summary"><strong>{{ month }} <span>月度计划</span></strong><span>{{ new Set(plans.map(p => p.employeeId)).size }}人 · {{ planDays }}人天</span><label class="search-field"><Icon name="search" :size="16" /><input v-model="search" placeholder="筛选员工姓名或编号" aria-label="筛选休假计划员工" /></label></div>
<div class="table-scroll vacation-matrix"><table class="schedule-table"><thead><tr><th class="sticky-name">员工 / 日期</th><th v-for="date in days" :key="date" :class="{'closed-day':!openOn(db,date)}"><span>{{ Number(date.slice(8)) }}</span><small>周{{ weekday(date) }}</small></th><th>计划天数</th></tr></thead><tbody><tr v-for="e in employees" :key="e.id"><th class="sticky-name">{{ e.name }}<small class="employee-code">{{ e.code }}</small></th><td v-for="date in days" :key="date" :class="{'closed-cell':!openOn(db,date)}"><button class="plan-cell" :class="{planned:!!vacationOn(db,e.id,date)}" :disabled="!activeOn(e,date)" :aria-label="`${e.name} ${date} ${vacationOn(db,e.id,date) ? '调整预定休假' : '新增预定休假'}`" :title="vacationOn(db,e.id,date)?.reason || (!openOn(db,date) ? '休息日；可按实际选择休假' : '点击设置休假')" @click="cellPlan(e.id,date)">{{ vacationOn(db,e.id,date) ? '预' : activeOn(e,date) ? (!openOn(db,date) ? '休' : '·') : '—' }}<sup v-if="vacationOn(db,e.id,date) && current?.cells[key(e.id,date)]?.kind === 'leave'">请</sup></button></td><td>{{ plans.filter(p => p.employeeId === e.id).reduce((n,p) => n+p.dates.length,0) }}</td></tr><tr v-if="!employees.length"><td :colspan="days.length+2" class="empty-table">暂无符合条件的在职员工，请先维护员工名单。</td></tr></tbody></table></div><footer class="panel-footer muted">计划按所选自然日计数。角标“请”表示该日另有事后请假，实际状态只计入请假，不重复计数。</footer></section>
<section class="panel top-gap"><header class="panel-header"><div><h2>休假计划明细</h2><p>修改或取消已配置计划后，请重新补排空位；原班次不会自动恢复。</p></div><span class="pill">{{ plans.length }}条计划</span></header><div class="table-scroll"><table class="data-table"><thead><tr><th>员工</th><th>休假日期</th><th>天数</th><th>说明</th><th>操作</th></tr></thead><tbody><tr v-for="p in plans" :key="p.id"><td>{{ db.employees.find(e => e.id === p.employeeId)?.name }}</td><td class="plan-dates">{{ p.dates.map(d => d.slice(5)).join('、') }}</td><td>{{ p.dates.length }}</td><td>{{ p.reason || '—' }}</td><td><div class="actions"><button class="text-button" @click="openPlan(p)">编辑</button><button class="text-button" @click="deletePlan = p; deleteDate = ''">取消计划</button></div></td></tr><tr v-if="!plans.length"><td colspan="5" class="empty-table">本月尚无预定休假。确认无需休假后可直接生成排班。</td></tr></tbody></table></div></section>
</template>
<section v-if="tab === '事后请假'" class="panel"><header class="panel-header"><div><h2>事后请假调整 <span class="pill leave-pill">排班后</span></h2><p>记录原排班确定后的临时请假，与预定休假分别管理。</p></div><button class="button primary" @click="openAdjustment('leave')">登记事后请假</button></header><div class="callout flat absence-note"><Icon name="info" :size="17" /><p>请假会替换所选日期班次，需补齐搭档与人数。与预定休假重叠时保留原计划；撤销请假后恢复该计划。</p></div><div class="table-scroll"><table class="data-table"><thead><tr><th>员工</th><th>日期</th><th>原计划</th><th>原因</th><th>操作</th></tr></thead><tbody><tr v-for="r in leaves" :key="`${r.employee.id}|${r.date}`"><td>{{ r.employee.name }}</td><td>{{ r.date }} <span class="pill leave-pill">请</span></td><td>{{ vacationOn(db,r.employee.id,r.date) ? '预定休假' : '—' }}</td><td>{{ r.note || '—' }}</td><td><div class="actions"><button class="text-button" @click="openAdjustment('leave',r.employee.id,r.date,r.note)">编辑</button><button class="text-button" @click="removeLeave(r.employee.id,r.date)">撤销请假</button></div></td></tr><tr v-if="!leaves.length"><td colspan="5" class="empty-table">当月没有事后请假记录。</td></tr></tbody></table></div><footer class="panel-footer muted">非预定休假日撤销请假后：开班日恢复未分配，休息日恢复休息。请重新补排。</footer></section>
<section v-if="tab === '个人休息'" class="panel"><header class="panel-header"><div><h2>个人休息与恢复可用</h2><p>个人调休不改变全体开班日。预定休假需在休假计划中取消。</p></div><button class="button primary" @click="openAdjustment('rest')">调整个人休息</button></header><div class="callout flat absence-note"><Icon name="shield" :size="17" /><p>休息、预定休假与事后请假都会受自动排班保护；恢复可用不会自动安排班次。</p></div></section>
<Modal :open="planOpen" :title="planId ? '编辑预定休假计划' : '新增预定休假计划'" wide @close="planOpen = false"><div class="form-grid"><label class="field">员工<select v-model="employeeId" :disabled="!!planId" aria-label="休假计划员工"><option value="" disabled>选择员工</option><option v-for="e in orderedEmployees(db)" :key="e.id" :value="e.id">{{ e.name }} · {{ e.code }}</option></select></label><label class="field">所属月份<input :value="month" type="month" disabled /></label><label class="field">范围开始<input v-model="from" type="date" :min="days[0]" :max="days.at(-1)" /></label><label class="field">范围结束<input v-model="to" type="date" :min="from" :max="days.at(-1)" /></label></div><div class="actions top-gap"><button class="button secondary" @click="expandRange(true)">选择范围内开班日</button><button class="button secondary" @click="expandRange(false)">选择范围内全部日期</button></div><p class="fineprint">也可逐日勾选，支持不连续休假。已选{{ chosenDates.length }}天。</p><div class="plan-date-picker"><label v-for="date in days" :key="date" :class="{checked:chosenDates.includes(date),off:!openOn(db,date)}"><input v-model="chosenDates" type="checkbox" :value="date" :aria-label="`休假日期${date}`" /><strong>{{ Number(date.slice(8)) }}</strong><small>周{{ weekday(date) }}</small></label></div><label class="field">休假说明<input v-model="planReason" placeholder="例如：预定年假、提前安排休假" /></label><p v-if="affectedShifts" class="inline-alert">保存将替换{{ affectedShifts }}个已有班次，请重新补排并检查每日两人配对。</p><p class="fineprint">已确认版本会保留并建立修订草稿。事后请假记录不被此计划覆盖。</p><template #footer><button v-if="planId && chosenDates.length" class="button secondary" @click="deletePlan = db.vacationPlans.find(p => p.id === planId); deleteDate = ''">取消整条计划</button><button class="button secondary" @click="planOpen = false">返回</button><button class="button primary" @click="submitPlan">保存休假计划</button></template></Modal>
<Modal :open="!!deletePlan" title="取消预定休假" @close="deletePlan = undefined"><p>取消后，开班日变为未分配，休息日恢复休息。事后请假继续保留。</p><p>已有班次不会自动恢复，请重新补排。</p><template #footer><button class="button secondary" @click="deletePlan = undefined">保留计划</button><button class="button primary" @click="confirmRemovePlan">确认取消计划</button></template></Modal>
<Modal :open="adjustmentOpen" :title="tab === '个人休息' ? '调整个人休息' : '事后请假调整'" @close="adjustmentOpen = false"><label class="field">员工<select v-model="adjustmentEmployee" :disabled="!!previousLeaveDate" aria-label="个人调整员工"><option value="" disabled>选择员工</option><option v-for="e in orderedEmployees(db)" :key="e.id" :value="e.id">{{ e.name }} · {{ e.code }}</option></select></label><div class="form-grid"><label class="field">开始日期<input v-model="adjustmentFrom" type="date" :min="days[0]" :max="days.at(-1)" /></label><label class="field">结束日期<input v-model="adjustmentTo" type="date" :min="adjustmentFrom" :max="days.at(-1)" /></label></div><label v-if="tab === '个人休息'" class="field">状态<select v-model="adjustmentKind"><option value="rest">个人休息</option><option value="unassigned">恢复可用（未分配）</option></select></label><label class="field">调整原因<textarea v-model="adjustmentNote" rows="3" /></label><p class="fineprint">按整天记录。不会自动恢复原班次或调整搭档。</p><template #footer><button class="button secondary" @click="adjustmentOpen = false">取消</button><button class="button primary" @click="saveAdjustment">保存调整</button></template></Modal>
</template>
